class ToastrService{constructor($mdToast){this.$mdToast=$mdToast}showErrorToast(errorMessage){if(!errorMessage){errorMessage="An unexpected error occurred. Please try again"}console.log("Error:",errorMessage);this.showToast(errorMessage)}showSuccessToast(successMessage){console.log("Success:",successMessage);this.showToast(successMessage)}showWarningToast(warningMessage){console.log("Warning:",warningMessage);this.showToast(warningMessage)}showToast(message){this.$mdToast.show(this.$mdToast.simple().textContent(message).position("top right").hideDelay(5e3))}}angular.module("uDispatch").service("toastrService",ToastrService);